window.__PAGES=window.__PAGES||{};window.__PAGES["pages/settings-organization-members.html"]="<!-- Settings: Organisasi — Anggota -->\n<style>\n.st-role-badge{display:inline-block;padding:2px 8px;border-radius:10px;font-size:11px;font-weight:600}\n.st-role-badge.admin{background:#fef3c7;color:#b45309}\n.st-role-badge.spv{background:#dbeafe;color:#2563eb}\n.st-role-badge.agent{background:#dcfce7;color:#15803d}\n.st-status-dot{display:inline-flex;align-items:center;gap:4px;font-size:12px}\n.st-status-dot::before{content:'';width:8px;height:8px;border-radius:50%;background:#9ca3af}\n.st-status-dot.online::before{background:#22c55e}\n.st-status-dot.busy::before{background:#f59e0b}\n.st-status-dot.offline::before{background:#9ca3af}\n.st-max-inputs{display:flex;gap:16px;align-items:flex-end}\n.st-max-inputs label{flex:1;font-size:13px;font-weight:500}\n.st-max-inputs label input{display:block;width:100%;padding:8px 10px;border:1px solid var(--border);border-radius:8px;margin-top:4px;font-size:13px;background:var(--bg)}\n.st-del-confirm{background:#fef2f2;border:1px solid #fecaca;border-radius:8px;padding:12px;font-size:13px;color:var(--danger);margin-top:10px}\n</style>\n\n<div class=\"settings-layout\">\n  <aside class=\"settings-sidenav\" id=\"stNav\"></aside>\n  <div class=\"settings-body\">\n    <div style=\"display:flex;align-items:center;justify-content:space-between;margin-bottom:16px\">\n      <div><h2 style=\"margin-bottom:4px\">Anggota</h2><p style=\"font-size:13px;color:var(--muted)\">Kelola anggota dan kapasitas percakapan.</p></div>\n      <button class=\"btn primary\" onclick=\"openAddMember()\">+ Tambah Anggota</button>\n    </div>\n\n    <div class=\"card\" style=\"padding:0;overflow:hidden\">\n      <table class=\"data-table\" id=\"membersTable\">\n        <thead><tr><th>Nama</th><th>Email</th><th>Role</th><th>Tim</th><th>Max Conv</th><th>Conv Saat Ini</th><th>Status</th><th>Aksi</th></tr></thead>\n        <tbody id=\"membersBody\"></tbody>\n      </table>\n    </div>\n\n    <!-- Edit max conversation modal -->\n    <div class=\"modal-overlay\" id=\"modalMaxConv\">\n      <div class=\"modal\">\n        <h3>Ubah Maks. Percakapan</h3>\n        <p style=\"font-size:13px;color:var(--muted);margin-bottom:14px\" id=\"maxConvAgent\"></p>\n        <div class=\"st-max-inputs\">\n          <label>Saat Ini (read-only)<input type=\"number\" id=\"maxConvCurrent\" readonly></label>\n          <label>Maks. Baru<input type=\"number\" id=\"maxConvNew\" min=\"1\"></label>\n        </div>\n        <div class=\"modal-actions\"><button class=\"btn\" onclick=\"closeModal('modalMaxConv')\">Batal</button><button class=\"btn primary\" onclick=\"saveMaxConv()\">Simpan</button></div>\n      </div>\n    </div>\n\n    <!-- Add member modal -->\n    <div class=\"modal-overlay\" id=\"modalAddMember\">\n      <div class=\"modal\">\n        <h3>Tambah Anggota</h3>\n        <label>Nama<input type=\"text\" id=\"addName\"></label>\n        <label>Email<input type=\"email\" id=\"addEmail\"></label>\n        <label>Role<select id=\"addRole\"><option value=\"agent\">Agent</option><option value=\"spv\">SPV</option><option value=\"admin\">Admin</option></select></label>\n        <label>Tim<select id=\"addTeam\"></select></label>\n        <label>Maks. Percakapan<input type=\"number\" id=\"addMaxConv\" value=\"20\" min=\"1\"></label>\n        <div class=\"modal-actions\"><button class=\"btn\" onclick=\"closeModal('modalAddMember')\">Batal</button><button class=\"btn primary\" onclick=\"saveAddMember()\">Tambah</button></div>\n      </div>\n    </div>\n\n    <!-- Remove confirm modal -->\n    <div class=\"modal-overlay\" id=\"modalRemove\">\n      <div class=\"modal\">\n        <h3>Hapus Anggota</h3>\n        <div class=\"st-del-confirm\" id=\"removeMsg\"></div>\n        <div class=\"modal-actions\"><button class=\"btn\" onclick=\"closeModal('modalRemove')\">Batal</button><button class=\"btn danger\" onclick=\"confirmRemove()\">Hapus</button></div>\n      </div>\n    </div>\n  </div>\n</div>\n\n<script>\n(function(){\n  document.getElementById('stNav').innerHTML=renderSettingsNav('organization-members');\n\n  const teams=DB.teams||[];\n  const users=DB.users||[];\n  let editingAgentId=null;\n\n  function teamName(tid){const t=teams.find(t=>t.id===tid);return t?t.name:'-'}\n\n  function render(){\n    const tbody=document.getElementById('membersBody');\n    if(!DB.agents.length){tbody.innerHTML='<tr><td colspan=\"8\" style=\"text-align:center;padding:32px;color:var(--muted)\">Belum ada anggota.</td></tr>';return}\n    tbody.innerHTML=DB.agents.map(a=>{\n      const u=users.find(u=>u.id===a.id);\n      const email=u?u.email:'-';\n      return `<tr style=\"cursor:pointer\" onclick=\"openMaxConv('${a.id}')\">\n        <td><div style=\"display:flex;align-items:center;gap:8px\"><div class=\"av\" style=\"background:var(--accent);width:28px;height:28px;font-size:10px\">${a.initials}</div>${a.name}</div></td>\n        <td style=\"font-size:12px;color:var(--muted)\">${email}</td>\n        <td><span class=\"st-role-badge ${a.role}\">${a.role.toUpperCase()}</span></td>\n        <td>${teamName(a.teamId)}</td>\n        <td>${a.maxConv}</td>\n        <td>${a.currentConv}</td>\n        <td><span class=\"st-status-dot ${a.status}\">${a.status}</span></td>\n        <td><button class=\"btn danger\" style=\"font-size:11px;padding:3px 10px\" onclick=\"event.stopPropagation();openRemove('${a.id}')\">Hapus</button></td>\n      </tr>`;\n    }).join('');\n  }\n  render();\n\n  window.openMaxConv=function(id){\n    editingAgentId=id;\n    const a=dbFind('agents',id);\n    document.getElementById('maxConvAgent').textContent=a.name;\n    document.getElementById('maxConvCurrent').value=a.maxConv;\n    document.getElementById('maxConvNew').value=a.maxConv;\n    document.getElementById('modalMaxConv').classList.add('open');\n  };\n\n  window.saveMaxConv=function(){\n    const v=parseInt(document.getElementById('maxConvNew').value);\n    if(v>0){dbUpdate('agents',editingAgentId,{maxConv:v});render();showToast('Maks. percakapan diperbarui')}\n    closeModal('modalMaxConv');\n  };\n\n  window.openAddMember=function(){\n    document.getElementById('addName').value='';\n    document.getElementById('addEmail').value='';\n    document.getElementById('addRole').value='agent';\n    document.getElementById('addMaxConv').value='20';\n    const sel=document.getElementById('addTeam');\n    sel.innerHTML=teams.map(t=>`<option value=\"${t.id}\">${t.name}</option>`).join('');\n    document.getElementById('modalAddMember').classList.add('open');\n  };\n\n  window.saveAddMember=function(){\n    const name=document.getElementById('addName').value.trim();\n    const email=document.getElementById('addEmail').value.trim();\n    if(!name){showToast('Nama wajib diisi');return}\n    const initials=name.split(' ').map(w=>w[0]).join('').toUpperCase().slice(0,2);\n    const newId=genId('u');\n    const agent={id:newId,name,initials,role:document.getElementById('addRole').value,teamId:document.getElementById('addTeam').value,currentConv:0,maxConv:parseInt(document.getElementById('addMaxConv').value)||20,status:'offline'};\n    dbAdd('agents',agent);\n    if(email){DB.users.push({id:newId,name,email,password:'',role:agent.role,initials,org:DB.settings.org.name});saveStore()}\n    render();closeModal('modalAddMember');showToast('Anggota ditambahkan');\n  };\n\n  let removeId=null;\n  window.openRemove=function(id){removeId=id;const a=dbFind('agents',id);document.getElementById('removeMsg').textContent=`Yakin ingin menghapus ${a.name}? Tindakan ini tidak dapat dibatalkan.`;document.getElementById('modalRemove').classList.add('open')};\n  window.confirmRemove=function(){dbRemove('agents',removeId);DB.users=DB.users.filter(u=>u.id!==removeId);saveStore();render();closeModal('modalRemove');showToast('Anggota dihapus')};\n\n  window.closeModal=function(id){document.getElementById(id).classList.remove('open')};\n})();\n</script>\n";
